<template>
  <section class="panel fire-section" v-loading="f.loading">

    <div v-if="f.permissions.canManage && f.pendingImports.length" class="pending-imports"><div v-for="preview in f.pendingImports" :key="preview.id"><div><strong>待核对台账 · {{ preview.filename }}</strong><small>{{ preview.counts?.rows || 0 }} 行 · {{ preview.counts?.warningCount || 0 }} 项待核实</small></div><el-button plain @click="f.resumeImport(preview.id)">核对导入</el-button></div></div>
    <form class="fire-filter-row fire-ledger-toolbar" @submit.prevent="f.loadPoints"><FireSectionFilter /><el-select v-model="f.query.areaId" clearable placeholder="全部区域" aria-label="台账区域"><el-option v-for="area in f.areas" :key="area.id" :label="area.name" :value="area.id" /></el-select><el-select v-model="f.query.type" clearable placeholder="全部器材" aria-label="台账器材类型"><el-option label="灭火器" value="extinguisher" /><el-option label="消防栓" value="hydrant" /></el-select><el-input v-model="f.query.q" placeholder="器材编码、点位或位置" aria-label="搜索器材台账" clearable /><el-button native-type="submit">查询</el-button><div class="heading-actions fire-ledger-actions"><template v-if="f.permissions.canManage"><el-button text @click="f.settingsVisible=true">区域权限</el-button><el-button @click="f.listAction('import')">导入台账</el-button><el-button type="primary" @click="f.editPoint()">录入器材</el-button></template><el-button :loading="f.printing" @click="f.printLabels">打印二维码</el-button></div></form>
    <el-alert v-if="f.listError" :title="f.listError" type="error" :closable="false" />
    <el-table class="fire-ledger-table" :data="rows" empty-text="暂无器材台账，请核对导入资料或录入器材" stripe><el-table-column label="器材编号" width="120"><template #default="{row}"><strong>{{ row.asset.code || '未填写' }}</strong><small v-if="(row.asset.source?.instanceIndex||row.asset.source?.unitIndex)>1" class="table-secondary">序位 {{ row.asset.source.instanceIndex||row.asset.source.unitIndex }}</small></template></el-table-column><el-table-column label="器材类型" width="115"><template #default="{row}">{{ row.asset.name || f.typeName(row.asset.type) }}</template></el-table-column><el-table-column label="规格" min-width="110"><template #default="{row}">{{ row.asset.spec || '—' }}</template></el-table-column><el-table-column label="工段" min-width="110"><template #default="{row}">{{ row.point.sectionName || '未分工段' }}</template></el-table-column><el-table-column label="所属区域" min-width="160"><template #default="{row}">{{ row.point.areaName }}</template></el-table-column><el-table-column label="具体位置" min-width="240"><template #default="{row}">{{ f.location(row.point) || row.point.name }}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}">{{ row.asset.quantity==null?'数量待核':f.assetStatus(row.asset.status) }}</template></el-table-column><el-table-column label="操作" width="200" fixed="right"><template #default="{row}"><div class="fire-ledger-row-actions"><el-button link type="primary" @click="f.openPoint(row.point.id,'assets',row.asset.id)">详情</el-button><el-button v-if="f.physicalAsset(row.asset)" link type="primary" @click="f.showQr(row.point,row.asset)">二维码</el-button><el-button v-if="f.permissions.canManage" link @click="f.editPoint(row.point)">维护</el-button></div></template></el-table-column></el-table>
    <div class="pagination-bar"><span class="fire-note">{{ f.points.length }} 个点位</span><el-pagination v-if="f.points.length>f.pageSize" v-model:current-page="f.pointPage" :page-size="f.pageSize" :total="f.points.length" layout="prev, pager, next" :pager-count="5" /></div>
  </section>
</template>
<script setup>
import FireSectionFilter from './FireSectionFilter.vue'
import { computed, inject } from 'vue'
import { fireMatchedAssets } from '../../utils/fire-inspection.mjs'
const f=inject('fireInspection')
const rows=computed(()=>f.displayedPoints.flatMap(point=>fireMatchedAssets(point).map(asset=>({point,asset}))))
</script>
